const SHIPPING_ZONES = {
  domestic: { countries: ['US', 'CA'], feeCents: 499 },
  gulf: { countries: ['AE', 'SA'], feeCents: 1299 },
  levant: { countries: ['EG', 'JO'], feeCents: 899 },
  europe: { countries: ['GB', 'DE'], feeCents: 999 },
} as const;

// Shape of the checkout API response (generated from the backend's schema).
type CheckoutResponse = {
  order: { id: number; status: 'processing' | 'shipped'; totalCents: number };
  lines: { sku: string; quantity: number; unitPriceCents: number }[];
};

type ShippingZones = typeof SHIPPING_ZONES;
type Zone = keyof ShippingZones;
type ShippingCountry = ShippingZones[Zone]['countries'][number];
type FeeCents = ShippingZones[Zone]['feeCents'];
type LineItem = CheckoutResponse['lines'][number];
type CheckoutStatus = CheckoutResponse['order']['status'];

function zoneFor(country: ShippingCountry): Zone {
  // SHIPPING_ZONES is our own const object, so it has no extra keys.
  for (const zone of Object.keys(SHIPPING_ZONES) as Zone[]) {
    if ((SHIPPING_ZONES[zone].countries as readonly string[]).includes(country)) return zone;
  }
  throw new Error(`No shipping zone for ${country}`);
}

function feeFor(country: ShippingCountry): FeeCents {
  return SHIPPING_ZONES[zoneFor(country)].feeCents;
}

// ---- Type tests (do not edit) ----
type T1 = Expect<Equal<Zone, 'domestic' | 'gulf' | 'levant' | 'europe'>>;
type T2 = Expect<Equal<ShippingCountry, 'US' | 'CA' | 'AE' | 'SA' | 'EG' | 'JO' | 'GB' | 'DE'>>;
type T3 = Expect<Equal<FeeCents, 499 | 1299 | 899 | 999>>;
type T4 = Expect<Equal<LineItem, { sku: string; quantity: number; unitPriceCents: number }>>;
type T5 = Expect<Equal<CheckoutStatus, 'processing' | 'shipped'>>;

function typeTests() {
  // @ts-expect-error: France is not in any shipping zone
  zoneFor('FR');
}

console.log(zoneFor('JO'), feeFor('SA'));
